        StringAssert.Contains(artifact.ModuleCode, "loader: (context) => slots.fieldLoader ? slots.fieldLoader(context) : null");
        StringAssert.Contains(artifact.ModuleCode, "\"defaultsTarget\": \"VSelectionControl\"");
