                    {
                        if (Value > 0)
                        {
                            builder.OpenComponent<ChildCard>(0);
                            builder.AddAttribute(1, "Value", Value);
                            builder.CloseComponent();
                        }

                        foreach (var item in Items)
                        {
                            builder.OpenElement(2, "li");
                            builder.AddContent(3, item);
                            builder.CloseElement();
                        }
                    }
                }
            }
            """);

