                    public int Value { get; set; }

                    private string FormatLeaf(int value)
                        => (value + 1).ToString();

                    private string FormatA(int value)
                        => "A:" + FormatLeaf(value);

                    private string FormatB(int value)
                        => "B:" + FormatLeaf(value);

                    protected override void BuildRenderTree(RenderTreeBuilder builder)
                    {
