        StringAssert.Contains(artifact.ModuleCode, "const __jazorImperativeComponentMetadata_NavShell = {");
        StringAssert.Contains(artifact.ModuleCode, "\"navigationTitle\"");
        StringAssert.Contains(artifact.ModuleCode, "\"top\"");
    }

